package io.baozhu.copilot; import io.baozhu.copilot.api.*; import io.baozhu.copilot.security.SqlSafetyValidator; import org.junit.jupiter.api.Test; import java.util.*; import static org.assertj.core.api.Assertions.assertThat; class CopilotUnitTests {@Test void suggestsRules(){var out=new io.baozhu.copilot.ai.HeuristicAiProvider().suggestRules("orders",List.of(new ColumnSpec("id","BIGINT",false,true),new ColumnSpec("amount","DECIMAL",true,false)),List.of(Map.of("id",1)),"orders");assertThat(out).extracting(RuleSuggestion::ruleType).contains("NOT_NULL","UNIQUE","NON_NEGATIVE");} @Test void rejectsWriteSql(){var r=new SqlSafetyValidator().review("DELETE FROM orders",Set.of("orders"));assertThat(r.safe()).isFalse();assertThat(r.violations()).isNotEmpty();}}